// ===== Sales Pipeline — Classify Leads =====
// The pipeline mixes three populations: real buyers, job seekers who came through the
// careers pages, and people who only downloaded the magazine PDF. It also holds the
// owner's own test submissions. Running one nurture sequence over all of them would
// send a sales pitch to job applicants — the same mistake that made a recipient of the
// last campaign reply asking about employment.
//
// This writes Email / Phone / Lead Type / Nurture Safe. It never sends anything.
// Anything it cannot classify confidently stays "غير مصنّف" with Nurture Safe = false,
// so a human decides rather than an automation guessing.

const INTERNAL_EMAILS = new Set([
  "dr.baher.magnas@gmail.com", "b.b.magnas@gmail.com",
  "business@businesspartner.sa", "business@businesspartnerksa.com",
]);
const INTERNAL_NAME = /(baher|باهر)\s*(magnas|مقنص|بكر)?/i;

const FREE_MAIL = new Set([
  "gmail.com","googlemail.com","hotmail.com","outlook.com","live.com","yahoo.com",
  "icloud.com","me.com","aol.com","protonmail.com","proton.me","yandex.com","msn.com",
]);

// Explicit statements that the person wants a job, not a service.
const JOB_SIGNALS = [
  "looking for", "job", "roles", "role i have applied", "cv", "resume", "vacancy",
  "أبحث عن عمل", "ابحث عن عمل", "وظيفة", "وظائف", "سيرتي الذاتية", "توظيفي", "أرغب بالعمل",
];

const RE_EMAIL = /[a-z0-9._%+'-]+@[a-z0-9][a-z0-9.-]*\.[a-z]{2,}/i;
const RE_PHONE = /(?:الجوال|الهاتف|phone|mobile)\s*[:：]\s*([+0-9][0-9\s-]{6,})/i;

const out = [];
const stats = { total: 0, prospect: 0, jobseeker: 0, download: 0, supplier: 0, internal: 0, unknown: 0, noEmail: 0 };

for (const item of $input.all()) {
  const j = item.json;
  const notes = String(j.property_notes || "");
  const title = String(j.property_opportunity_name || j.name || "");
  const blob = (title + " " + notes).toLowerCase();
  stats.total++;

  const em = notes.match(RE_EMAIL);
  const email = em ? em[0].toLowerCase() : "";
  const ph = notes.match(RE_PHONE);
  const phone = ph ? ph[1].trim() : "";
  if (!email) stats.noEmail++;

  const domain = email.split("@")[1] || "";
  const isFree = FREE_MAIL.has(domain);
  const corporate = Boolean(domain) && !isFree;

  let type = "غير مصنّف";
  let safe = false;

  if (email && INTERNAL_EMAILS.has(email)) {
    type = "اختبار داخلي";
  } else if (INTERNAL_NAME.test(title)) {
    type = "اختبار داخلي";
  } else if (/تسجيل مورّد|تسجيل مورد|مورّد/.test(title)) {
    type = "مورّد";
  } else if (/تسجيل مجلة|magazine pdf gate/i.test(blob)) {
    type = "تحميل محتوى";
  } else if (JOB_SIGNALS.some((s) => blob.includes(s))) {
    type = "باحث عن عمل";
  } else if (corporate) {
    // A company domain plus an inbound request is the clearest buyer signal available.
    type = "عميل محتمل";
    safe = true;
  } else if (/طلب\/شراء|تقسيط|طلب مساحة عمل|فتح حساب بنكي|صفقة/.test(title)) {
    // Transactional intent outweighs a free-mail address.
    type = "عميل محتمل";
    safe = true;
  }
  // Everything else — a bare consultation request from a free address with no stated
  // intent — is genuinely ambiguous. Those are exactly the rows that could be either a
  // small-business owner or a job seeker, so they wait for a human.

  if (type === "عميل محتمل") stats.prospect++;
  else if (type === "باحث عن عمل") stats.jobseeker++;
  else if (type === "تحميل محتوى") stats.download++;
  else if (type === "مورّد") stats.supplier++;
  else if (type === "اختبار داخلي") stats.internal++;
  else stats.unknown++;

  out.push({ json: {
    _pageId: j.id, _email: email, _phone: phone, _type: type,
    _safe: safe && Boolean(email), _title: title,
  }});
}

console.log("CLASSIFY", JSON.stringify(stats));
return out;
